package example.shop.order.domain;public record Actor(ActorType type,String id,String displayName){public enum ActorType{CUSTOMER,SUPPORT,WAREHOUSE,ADMIN,SYSTEM,ANONYMOUS}public static final Actor SYSTEM=new Actor(ActorType.SYSTEM,"system","system");public static final Actor ANONYMOUS=new Actor(ActorType.ANONYMOUS,"anonymous","anonymous");public boolean isCustomer(){return type==ActorType.CUSTOMER;}public boolean isSupport(){return type==ActorType.SUPPORT;}public boolean isInternal(){return type==ActorType.SUPPORT||type==ActorType.ADMIN||type==ActorType.WAREHOUSE;}public boolean isPrivileged(){return isInternal()||type==ActorType.SYSTEM;}}